                title: '‘A’ is for adultery',
                publication: 'Northern Star — Weekender · “The Scarlet Letter”',
                credit: 'By Chaz Wilke, Weekender Reporter',
                format: 'Theater review · NIU student production',
                depthLabel: 'Clipping + pull quote',
