                imageAlt: 'The Oct. 30, 2003 clipping of "Peace, love and nakedness," with a photo of a performer with arms outstretched on a scaffolded stage',
                dek: 'A revival of “Hair” reviewed by a writer more interested in the audience than the stage — specifically in how quiet a room gets when the nudity finally arrives.',
                curator: 'Sources the review to people who were alive for the era rather than to other students, and gets the sharpest line in the piece from a middle-aged audience member: that it is sad the show had to be marketed on nudity to fill seats. Then closes by cheerfully undercutting her.',
