                            type: 'paragraph',
                            text: 'Just as Dane reaches his big question, a breaking-news graphic interrupts the package. The anchors return to the desk for a surprise press conference from the NoHo comptroller. Dane hears “controller,” Kelly Mae corrects him, and the episode is already moving into its next civic disaster.'
